using System;\nusing System.Net;\nusing System.Threading.Tasks;\nusing Newtonsoft.Json.Linq;\nusing RestSharp;\nusing Serilog;\nusing TechTalk.SpecFlow;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetstoreCRUDSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly RestClient _client;\n        private RestResponse _response;\n\n        public PetstoreCRUDSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _client = new RestClient(\"https://petstore.swagger.io/v2\");\n        }\n\n        [Given(@\"I have a pet payload with id \"(.*)\"\", name \"(.*)\"\", and status \"(.*)\"\")]\n        public void GivenIHaveAPetPayloadWithIdNameAndStatus(string id, string name, string status)\n        {\n            var payload = new JObject\n            {\n                { \"id\", id },\n                { \"name\", name },\n                { \"status\", status }\n            };\n            _scenarioContext[\"payload\"] = payload.ToString();\n        }\n\n        [Given(@\"I have a pet id \"(.*)\"\")]\n        public void GivenIHaveAPetId(string id)\n        {\n            _scenarioContext[\"petId\"] = id;\n        }\n\n        [When(@\"I send a POST request to the petstore API\")]\n        public async Task WhenISendAPOSTRequestToThePetstoreAPI()\n        {\n            var request = new RestRequest(\"/pet\", Method.Post);\n            request.AddJsonBody(_scenarioContext[\"payload\"]);\n            _response = await _client.ExecuteAsync(request);\n            Log.Information(\"POST Request: {Endpoint}, Payload: {Payload}, Status Code: {StatusCode}, Response: {Response}\",\n                request.Resource, _scenarioContext[\"payload\"], _response.StatusCode, _response.Content);\n        }\n\n        [When(@\"I send a GET request to the petstore API\")]\n        public async Task WhenISendAGETRequestToThePetstoreAPI()\n        {\n            var request = new RestRequest($\"/pet/{_scenarioContext[\"petId\"]}\", Method.Get);\n            _response = await _client.ExecuteAsync(request);\n            Log.Information(\"GET Request: {Endpoint}, Status Code: {StatusCode}, Response: {Response}\",\n                request.Resource, _response.StatusCode, _response.Content);\n        }\n\n        [When(@\"I send a PUT request to the petstore API\")]\n        public async Task WhenISendAPUTRequestToThePetstoreAPI()\n        {\n            var request = new RestRequest(\"/pet\", Method.Put);\n            request.AddJsonBody(_scenarioContext[\"payload\"]);\n            _response = await _client.ExecuteAsync(request